# generate primes up to 200
primes = list(sp.primerange(2, 200))

solutions = []
for p in primes:
    for q in primes:
        for r in primes:
            # consider all sign assignments
            for sp1 in [1, -1]:
                for sp2 in [1, -1]:
                    for sp3 in [1, -1]:
                        a, b, c = sp1*p, sp2*q, sp3*r
                        if a + b + c != 0:
                            continue
                        if a*b + a*c + b*c != -147:
                            continue
                        prod = a*b*c
                        solutions.append((a, b, c, abs(-prod)))

# deduplicate
unique_answers = set(sol[3] for sol in solutions)
print(f"Unique answers: {unique_answers}")
# print one solution
if solutions:
    a, b, c, ans = solutions[0]
    print(f"Example roots: {a}, {b}, {c}")
    print(f"Answer: {ans}")
    print(f"ANSWER: {sp.latex(ans)}")
