# Precompute all row patterns with exactly two '1's in a 6x6 grid
patterns = []
for i in range(6):
    for j in range(i+1, 6):
        patterns.append((i, j))  # store column indices of 1s

# Union-Find data structure
class UnionFind:
    def __init__(self, n):
        self.parent = list(range(n))
    def find(self, x):
        while self.parent[x] != x:
            self.parent[x] = self.parent[self.parent[x]]
            x = self.parent[x]
        return x
    def union(self, x, y):
        fx, fy = self.find(x), self.find(y)
        if fx != fy:
            self.parent[fy] = fx
    def count_sets(self):
        roots = set()
        for i in range(len(self.parent)):
            roots.add(self.find(i))
        return len(roots)

total_sum = 0  # Python int for accumulation

# Recursive search with pruning
def search(row_index, col_sums, rows_selected):
    global total_sum
    if row_index == 6:
        # All rows selected, all column sums should be exactly 2
        # Build pebbles list
        pebbles = []  # list of (row, col)
        for r, pat in enumerate(rows_selected):
            for c in pat:
                pebbles.append((r, c))
        n_peb = len(pebbles)  # should be 12
        uf = UnionFind(n_peb)
        # Map rows to pebble indices
        row_pebs = [[] for _ in range(6)]
        col_pebs = [[] for _ in range(6)]
        for idx, (r, c) in enumerate(pebbles):
            row_pebs[r].append(idx)
            col_pebs[c].append(idx)
        # Union pebbles in same row
        for lst in row_pebs:
            for i in range(1, len(lst)):
                uf.union(lst[0], lst[i])
        # Union pebbles in same column
        for lst in col_pebs:
            for i in range(1, len(lst)):
                uf.union(lst[0], lst[i])
        f = uf.count_sets()
        total_sum += 1 << f  # 2**f
        return

    # Prune if any column sum > 2 or required > remaining rows
    for c in range(6):
        if col_sums[c] > 2:
            return
    remaining_rows = 6 - row_index
    for c in range(6):
        needed = 2 - col_sums[c]
        if needed > remaining_rows:
            return

    # Iterate over all patterns for this row
    for pat in patterns:
        # Update column sums
        new_col_sums = list(col_sums)
        for c in pat:
            new_col_sums[c] += 1
        # Quick prune
        if any(s > 2 for s in new_col_sums):
            continue
        search(row_index + 1, new_col_sums, rows_selected + [pat])

# Start recursion
search(0, [0]*6, [])

# Output answer
ans = Integer(total_sum)
print(f"ANSWER: {latex(ans)}")
