from sympy import Matrix, GF, Integer, latex

total = Integer(0)

for n in range(1, 11):
    for k in range(1, n + 1):
        vectors = []
        for i in range(2**n):
            if bin(i).count("1") == k:
                vec = [int(bit) for bit in format(i, f"0{n}b")]
                vectors.append(vec)
        if vectors:
            mat = Matrix(vectors).applyfunc(lambda x: x % 2)
            rank = mat.rank(domain=GF(2))
            components = Integer(2**(n - rank))
        else:
            # no vertices with weight k (should not happen for 1 <= k <= n)
            components = Integer(0)
        total += components

print(f"ANSWER: {latex(total)}")
